// FIX: Helper function to normalize dates for comparison
// This handles both Date objects and ISO string dates from mocks
const normalizeDateValue = (value) => {
  if (!value) return null;

  // If it's a Date object, convert to ISO string
  if (value instanceof Date) {
    return value.toISOString();
  }

  // If it's a string, ensure it's a valid ISO date
  if (typeof value === 'string') {
    // Validate it's a valid ISO string
    const parsed = new Date(value);
    if (!isNaN(parsed.getTime())) {
      return parsed.toISOString();
    }
  }

  return String(value);
};

// FIX: Helper function to normalize all dates in an object/array
const normalizeAllDates = (data) => {
  if (Array.isArray(data)) {
    return data.map(item => normalizeAllDates(item));
  }

  if (data && typeof data === 'object') {
    const normalized = {};
    for (const [key, value] of Object.entries(data)) {
      // Check if key looks like a date field
      if (key.includes('_at') || key.toLowerCase().includes('date') || key.toLowerCase().includes('created') || key.toLowerCase().includes('updated')) {
        normalized[key] = normalizeDateValue(value);
      } else {
        // Recursively handle nested objects
        normalized[key] = value && typeof value === 'object' ? normalizeAllDates(value) : value;
      }
    }
    return normalized;
  }

  return data;
};

