/**
 * Webhook Signature Verification Middleware
 * 
 * SECURITY CRITICAL: Verifies HMAC-SHA256 signatures for incoming webhooks.
 * This prevents unauthorized sources from triggering webhook handlers.
 * 
 * Usage:
 *   // Apply to specific webhook routes
 *   router.post('/webhooks/meta', verifyWebhookSignature('meta'), handler);
 *   
 *   // Or apply globally to all webhook routes
 *   app.use('/webhooks', verifyWebhookSignature('incoming'));
 * 
 * Supports multiple secret sources:
 * - Per-request header (X-Webhook-Secret)
 * - Environment variable fallback
 * - Database lookup by app_id or asset_id
 * 
 * Headers checked (in order):
 * - X-Hub-Signature-256 (Meta Graph API format: sha256=hex)
 * - X-Signature-256 (Generic format: sha256=hex)
 * - X-Webhook-Signature (Alternative format: hex)
 * 
 * @file middleware/webhook-signature.middleware.js
 */

const crypto = require('crypto');
const { AppError } = require('../utils/AppError');
const { createLogger } = require('../utils/structured-logger');

const logger = createLogger('WebhookSignatureMiddleware');

/**
 * Timing-safe comparison of two buffers
 * Prevents timing attacks that could reveal signature information
 * 
 * @param {Buffer} a - Expected signature buffer
 * @param {Buffer} b - Received signature buffer
 * @returns {boolean} True if buffers match
 */
const timingSafeCompare = (a, b) => {
  try {
    return crypto.timingSafeEqual(a, b);
  } catch (error) {
    // In case of length mismatch or other comparison error
    logger.warn('Timing safe compare failed', { error: error.message });
    return false;
  }
};

/**
 * Verify HMAC-SHA256 signature against raw body
 * 
 * @param {Buffer} rawBody - Raw request body (must be Buffer, not parsed JSON)
 * @param {string} receivedSignature - Signature from header (format: 'sha256=hex' or 'hex')
 * @param {string} secret - HMAC secret
 * @returns {boolean} True if signature is valid
 */
const verifyHmacSignature = (rawBody, receivedSignature, secret) => {
  if (!receivedSignature || !secret) {
    logger.warn('Missing signature or secret during verification');
    return false;
  }

  // Extract hex value from signature (format: 'sha256=hex' or just 'hex')
  const receivedHex = receivedSignature.includes('=') 
    ? receivedSignature.split('=')[1]
    : receivedSignature;

  if (!receivedHex) {
    logger.warn('Cannot extract hex from signature format', { receivedSignature });
    return false;
  }

  // Calculate expected signature
  const expectedHex = crypto
    .createHmac('sha256', secret)
    .update(rawBody)
    .digest('hex');

  // Use timing-safe comparison to prevent timing attacks
  const expectedBuf = Buffer.from(expectedHex, 'hex');
  const receivedBuf = Buffer.from(receivedHex, 'hex');

  const isValid = timingSafeCompare(expectedBuf, receivedBuf);

  if (!isValid) {
    logger.warn('Webhook signature mismatch', {
      receivedLength: receivedBuf.length,
      expectedLength: expectedBuf.length
    });
  }

  return isValid;
};

/**
 * Retrieve webhook secret from various sources
 * Priority: header > database > environment variable
 * 
 * @param {Object} req - Express request object
 * @param {string} webhookType - Type of webhook (e.g., 'meta', 'shopify')
 * @returns {Promise<string|null>} Secret or null if not found
 */
const getWebhookSecret = async (req, webhookType = 'default') => {
  // 1. Check if secret is passed in custom header (not recommended for production)
  if (req.headers['x-webhook-secret']) {
    logger.debug('Using secret from request header');
    return req.headers['x-webhook-secret'];
  }

  // 2. Try to look up secret from database if app_id or asset_id in payload
  if (req.body && typeof req.body === 'string') {
    try {
      const payload = JSON.parse(req.body);

      // Meta webhooks: Look up by asset_id
      if (webhookType === 'meta' && payload.entry?.[0]?.id) {
        const MetaIntegration = require('../modules/integration/meta-integration.entity');
        const integration = await MetaIntegration.findOne({
          where: {
            meta_asset_id: payload.entry[0].id,
            status: 'CONNECTED'
          }
        });

        if (integration?.app_secret) {
          logger.debug('Using per-tenant secret from database', { assetId: payload.entry[0].id });
          return integration.app_secret;
        }
      }

      // Shopify webhooks: Look up by shop domain
      if (webhookType === 'shopify' && payload.domain) {
        const ShopifyIntegration = require('../modules/integration/shopify-integration.entity');
        const integration = await ShopifyIntegration.findOne({
          where: {
            shop_domain: payload.domain,
            status: 'CONNECTED'
          }
        });

        if (integration?.webhook_secret) {
          logger.debug('Using per-shop secret from database', { domain: payload.domain });
          return integration.webhook_secret;
        }
      }
    } catch (parseError) {
      logger.debug('Could not parse body for database lookup');
    }
  }

  // 3. Fall back to environment variable
  const envKey = `${webhookType.toUpperCase()}_WEBHOOK_SECRET`;
  const envSecret = process.env[envKey];

  if (envSecret) {
    logger.debug('Using secret from environment variable', { envKey });
    return envSecret;
  }

  return null;
};

/**
 * Express middleware factory for webhook signature verification
 * 
 * Features:
 * - MANDATORY signature verification (returns 403 if invalid)
 * - Support for multiple header formats (Meta, generic, alternate)
 * - Timing-safe comparison (prevents timing attacks)
 * - Detailed security logging
 * - Per-tenant secret lookup
 * - Graceful fallback to environment secrets
 * 
 * @param {string} webhookType - Type of webhook for logging and secret lookup (default: 'incoming')
 * @param {Object} options - Additional options
 * @param {boolean} options.requireSignature - Fail if signature missing (default: true)
 * @param {Function} options.secretLookup - Custom function to retrieve secret
 * @returns {Function} Express middleware
 * 
 * @example
 * // Apply to Meta webhook route
 * router.post(
 *   '/meta/comment-to-dm',
 *   express.raw({ type: 'application/json' }),
 *   verifyWebhookSignature('meta'),
 *   commentToDmHandler
 * );
 * 
 * @example
 * // Apply to Shopify webhook route with custom secret lookup
 * router.post(
 *   '/shopify/orders',
 *   express.raw({ type: 'application/json' }),
 *   verifyWebhookSignature('shopify', {
 *     secretLookup: async (req) => {
 *       return await shopifySecretsService.getByShopId(req.user?.shopId);
 *     }
 *   }),
 *   shopifyOrderHandler
 * );
 */
const verifyWebhookSignature = (webhookType = 'incoming', options = {}) => {
  const {
    requireSignature = true,
    secretLookup = null
  } = options;

  return async (req, res, next) => {
    try {
      const requestId = req.requestId || req.headers['x-request-id'];

      // Check for signature header (required)
      const signature = req.headers['x-hub-signature-256'] 
        || req.headers['x-signature-256']
        || req.headers['x-webhook-signature'];

      if (requireSignature && !signature) {
        logger.error('SECURITY: Missing webhook signature header', {
          webhookType,
          requestId,
          url: req.originalUrl,
          headers: Object.keys(req.headers)
        });
        throw new AppError(
          'Missing X-Hub-Signature-256 or X-Signature-256 header. Webhook signature verification failed.',
          403
        );
      }

      // If no signature and not required, proceed
      if (!signature) {
        logger.info('Webhook signature not required, proceeding');
        return next();
      }

      // Get raw body (middleware should use express.raw({ type: '...' }))
      const rawBody = req.body instanceof Buffer
        ? req.body
        : Buffer.from(String(req.body || ''));

      // Retrieve webhook secret
      let secret = secretLookup 
        ? await secretLookup(req) 
        : await getWebhookSecret(req, webhookType);

      if (!secret) {
        logger.error('SECURITY: No webhook secret configured', {
          webhookType,
          requestId,
          url: req.originalUrl
        });
        throw new AppError(
          `No webhook secret configured for ${webhookType}. Unable to verify signature.`,
          403
        );
      }

      // Verify signature
      const isValid = verifyHmacSignature(rawBody, signature, secret);

      if (!isValid) {
        logger.error('SECURITY: Invalid webhook signature', {
          webhookType,
          requestId,
          url: req.originalUrl,
          signatureFormat: signature.substring(0, 10) + '...',
          reason: 'HMAC-SHA256 mismatch'
        });
        throw new AppError(
          'Invalid webhook signature. HMAC-SHA256 verification failed.',
          403
        );
      }

      // Signature verified successfully
      logger.info('Webhook signature verified', {
        webhookType,
        requestId,
        url: req.originalUrl
      });

      // Attach verification metadata to request
      req.webhookVerified = true;
      req.webhookType = webhookType;

      next();
    } catch (error) {
      logger.error('Webhook signature verification error', {
        webhookType,
        error: error.message,
        requestId: req.requestId
      });
      next(error);
    }
  };
};

module.exports = {
  verifyWebhookSignature,
  verifyHmacSignature,
  timingSafeCompare,
  getWebhookSecret
};

/**
 * Response Standardization Middleware
 * 
 * Ensures all API responses follow a consistent format:
 * 
 * SUCCESS (2xx):
 * {
 *   success: true,
 *   data: any,
 *   message?: string,
 *   requestId: string,
 *   timestamp: ISO string
 * }
 * 
 * ERROR (4xx, 5xx) - handled by globalErrorHandler in AppError.js:
 * {
 *   success: false,
 *   message: string,
 *   code: string,
 *   requestId: string,
 *   path: string,
 *   method: string,
 *   timestamp?: ISO string
 * }
 * 
 * Usage:
 *   app.use(responseStandardization());
 *   // Must be placed BEFORE route handlers but AFTER request context middleware
 * 
 * Pairs with globalErrorHandler in AppError.js which handles error responses.
 * 
 * @file middleware/response-standardization.middleware.js
 */

const { createLogger } = require('../utils/structured-logger');
const logger = createLogger('ResponseStandardization');

/**
 * Check if response body is already in standard format
 * to avoid double-wrapping
 * 
 * @param {any} body - Response body to check
 * @returns {boolean} True if already standardized
 */
const isStandardized = (body) => {
  if (!body || typeof body !== 'object') {
    return false;
  }

  // Already has success field (our format)
  if ('success' in body) {
    return true;
  }

  // Has both these fields which indicate it's already structured
  if ('data' in body && 'message' in body) {
    return true;
  }

  return false;
};

/**
 * Override res.json() to add standardization
 * Wraps response with success: true if not already formatted
 * 
 * @param {Object} req - Express request
 * @param {Object} res - Express response
 * @param {Function} next - Express next middleware
 */
const responseStandardization = () => {
  return (req, res, next) => {
    const originalJson = res.json;
    const requestId = req.requestId || req.headers['x-request-id'] || null;
    const startTime = Date.now();

    // Override res.json() to add standardization
    res.json = function(body) {
      const statusCode = res.statusCode || 200;
      const isSuccess = statusCode >= 200 && statusCode < 400;
      const isError = statusCode >= 400;

      // Ensure body is object
      let data = body;
      if (typeof body !== 'object' || body === null) {
        data = { message: String(body) };
      }

      // If error response: let globalErrorHandler standardize it
      // (errors go through next(error), not res.json())
      if (isError && !isStandardized(data)) {
        // This shouldn't happen in normal flow, but safeguard
        logger.warn('Error response via res.json() (should use next(error))', {
          statusCode,
          requestId
        });
        return originalJson.call(this, {
          success: false,
          message: data.message || 'Internal Server Error',
          code: String(statusCode),
          requestId
        });
      }

      // If already standardized, return as-is
      if (isStandardized(data)) {
        // But ALWAYS ensure success flag is set correctly for status code
        if (isSuccess && data.success !== true) {
          data.success = true;
        }
        if (data.requestId === undefined) {
          data.requestId = requestId;
        }
        return originalJson.call(this, data);
      }

      // Standardize success response
      if (isSuccess) {
        const standardized = {
          success: true,
          ...(data.data !== undefined ? { data: data.data } : { data }),
          ...(data.message && { message: data.message }),
          requestId,
          timestamp: new Date().toISOString()
        };

        // Log response for observability
        const duration = Date.now() - startTime;
        logger.debug('API Response', {
          method: req.method,
          url: req.originalUrl,
          statusCode,
          requestId,
          duration
        });

        return originalJson.call(this, standardized);
      }

      // Fallback for unexpected status codes
      logger.warn('Unexpected status code in res.json', {
        statusCode,
        requestId
      });
      return originalJson.call(this, data);
    };

    next();
  };
};

/**
 * Response metadata extractor
 * Useful for monitoring and observability
 * 
 * Usage:
 *   const metadata = extractResponseMetadata(req, res);
 *   logger.info('Request completed', metadata);
 */
const extractResponseMetadata = (req, res) => {
  return {
    requestId: req.requestId,
    method: req.method,
    url: req.originalUrl,
    statusCode: res.statusCode,
    contentLength: res.getHeader('content-length'),
    timestamp: new Date().toISOString()
  };
};

module.exports = {
  responseStandardization,
  extractResponseMetadata,
  isStandardized
};
